package main

import "fmt"

func main() {
	s := make([]int, 0, 2) // len 0, cap 2
	for i := 1; i <= 5; i++ {
		s = append(s, i) // assign the result back!
		fmt.Printf("len=%d cap=%d %v\n", len(s), cap(s), s)
	}
	// len=1 cap=2 [1]
	// len=2 cap=2 [1 2]
	// len=3 cap=4 [1 2 3]
	// len=4 cap=4 [1 2 3 4]
	// len=5 cap=8 [1 2 3 4 5]
}
